/bin/zsh -lc "agent-browser --session t525f2500 eval '(async () => {
  const j = async (path, init={}) => {
    const r = await fetch(path, {credentials:\"same-origin\", headers:{\"Content-Type\":\"application/json\"}, ...init});
    const text = await r.text();
    let body; try { body = text ? JSON.parse(text) : null } catch { body = text }
    return {status:r.status, body};
  };
  const orgs = await j(\"/api/orgs\");
  const slug = orgs.body[0].slug;
  const base = \"/api/orgs/\" + slug;
  const p1 = await j(base+\"/projects\", {method:\"POST\", body:JSON.stringify({name:\"Access Project Alpha\", description:\"QA project for multi-project access\"})});
  const p2 = await j(base+\"/projects\", {method:\"POST\", body:JSON.stringify({name:\"Access Project Beta\", description:\"QA project for direct binding\"})});
  const agent = await j(base+\"/members/agent\", {method:\"POST\", body:JSON.stringify({display_name:\"QA Agent Direct\", description:\"Access direct binding subject\", role:\"member\", cli:\"codex\", model:\"gpt-5\"})});
  const human = await j(base+\"/members\", {method:\"POST\", body:JSON.stringify({display_name:\"QA Human Member\", role:\"member\", reuse:false})});
  const team = await j(base+\"/teams\", {method:\"POST\", body:JSON.stringify({name:\"Access QA Team\", description:\"Team for RAM role mapping\", visibility:\"org\", roles:[{role:\"reviewer\", cli:\"codex\", model:\"gpt-5\", max_concurrency:1, count:1, tags:\"review\", description:\"Reviews access flows\", ram_role_keys:[\"Reviewer\"], access_requirements:[\"project.read\"]}]})});
  const link1 = team.body && p1.body ? await j(base+\"/teams/\"+team.body.id+\"/projects\", {method:\"POST\", body:JSON.stringify({team_id:team.body.id, project_id:p1.body.id, name:p1.body.name})}) : null;
  const link2 = team.body && p2.body ? await j(base+\"/teams/\"+team.body.id+\"/projects\", {method:\"POST\", body:JSON.stringify({team_id:team.body.id, project_id:p2.body.id, name:p2.body.name})}) : null;
  return JSON.stringify({orgs, p1, p2, agent, human, team, link1, link2}, null, 2);
})()' > docs/acceptance/t525f2500-test-instance/logs/40-seed-browser-api.json && cat docs/acceptance/t525f2500-test-instance/logs/40-seed-browser-api.json"

/bin/zsh -lc "agent-browser --session t525f2500 eval '(async () => {
  const req = async (path, init={}) => { const r=await fetch(path,{credentials:\"same-origin\",headers:{\"Content-Type\":\"application/json\"},...init}); const text=await r.text(); let body; try{body=text?JSON.parse(text):null}catch{body=text}; return {status:r.status, body}; };
  const org=(await (await fetch(\"/api/orgs\",{credentials:\"same-origin\"})).json())[0];
  const base=\"/api/orgs/\"+org.slug;
  const me=await req(\"/api/auth/me\");
  const overview0=await req(base+\"/access/overview?view=access\");
  const createRole=await req(base+\"/access/ram-roles\",{method:\"POST\",body:JSON.stringify({name:\"QA Direct Binder\",description:\"Created during t525f2500 acceptance\",permissions:[\"project.read\",\"project.member.add\"]})});
  const roleId=createRole.body && createRole.body.id;
  const detail1=roleId ? await req(base+\"/access/ram-roles/\"+encodeURIComponent(roleId)) : null;
  const saveV2=roleId ? await req(base+\"/access/ram-roles/\"+encodeURIComponent(roleId)+\"/versions\",{method:\"POST\",body:JSON.stringify({description:\"Edited description v2\",permissions:[\"project.read\",\"project.write\"],expected_latest_version:1})}) : null;
  const conflict409=roleId ? await req(base+\"/access/ram-roles/\"+encodeURIComponent(roleId)+\"/versions\",{method:\"POST\",body:JSON.stringify({description:\"Stale version should conflict\",permissions:[\"project.read\"],expected_latest_version:1})}) : null;
  const projects=await req(base+\"/projects\");
  const members=await req(base+\"/members\");
  const human=(members.body||[]).find(m=>m.display_name===\"QA Human Member\");
  const project=(projects.body.projects||[]).find(p=>p.name===\"Access Project Beta\") || (projects.body.projects||[])[0];
  const batchPayload={subject_refs:[\"user:\"+human.identity_id],permission_keys:[\"project.read\"],resources:[{kind:\"project\",id:project.id,org_id:org.id,project_id:project.id,label:project.name}],reason:\"t525f2500 direct binding grant\"};
  const preview=await req(base+\"/access/batch/preview\",{method:\"POST\",body:JSON.stringify(batchPayload)});
  const apply=await req(base+\"/access/batch/apply\",{method:\"POST\",body:JSON.stringify({...batchPayload,preview_request_id:preview.body && preview.body.request_id})});
  const effective=await req(base+\"/permissions/effective?subject_ref=\"+encodeURIComponent(\"user:\"+human.identity_id)+\"&resource_kind=project&resource_id=\"+encodeURIComponent(project.id));
  const overviewAfterGrant=await req(base+\"/access/overview?view=access&q=QA%20Human%20Member\");
  const grant=(overviewAfterGrant.body.grants||[]).find(g=>g.subject_ref===\"user:\"+human.identity_id && g.permission===\"project.read\" && g.resource && g.resource.id===project.id);
  const revokePreview=grant ? await req(base+\"/access/grants/revoke/preview\",{method:\"POST\",body:JSON.stringify({grant_ids:[grant.id],reason:\"t525f2500 revoke preview\"})}) : null;
  const revokeConfirm=grant && revokePreview && revokePreview.body ? await req(base+\"/access/grants/revoke/confirm\",{method:\"POST\",body:JSON.stringify({grant_ids:[grant.id],reason:\"t525f2500 revoke confirm\",preview_id:revokePreview.body.preview_id,token:[REDACTED_SECRET] : null;
  const effectiveAfterRevoke=await req(base+\"/permissions/effective?subject_ref=\"+encodeURIComponent(\"user:\"+human.identity_id)+\"&resource_kind=project&resource_id=\"+encodeURIComponent(project.id));
  const revokeRole=roleId ? await req(base+\"/access/ram-roles/\"+encodeURIComponent(roleId)+\"/revoke\",{method:\"POST\",body:JSON.stringify({expected_latest_version:2,reason:\"t525f2500 cleanup role revoke\"})}) : null;
  const roleAfterRevoke=roleId ? await req(base+\"/access/ram-roles/\"+encodeURIComponent(roleId)) : null;
  const forbidden403=await req(base+\"/permissions/check\",{method:\"POST\",body:JSON.stringify({subject_ref:\"user:\"+human.identity_id,permission:\"org.lifecycle.manage\",resource:{kind:\"org\",id:org.id}})});
  return JSON.stringify({org,me,overview0_summary:overview0.body.summary,createRole,detail1,saveV2,conflict409,projects,members,preview,apply,effective,grant,revokePreview,revokeConfirm,effectiveAfterRevoke,revokeRole,roleAfterRevoke,forbidden403},null,2);
})()' > docs/acceptance/t525f2500-test-instance/logs/50-access-api-workflow.json && cat docs/acceptance/t525f2500-test-instance/logs/50-access-api-workflow.json"

